$forums_type = function_exists( 'bbp_get_forum_post_type' ) ? bbp_get_forum_post_type() : 'forum';
$topics = get_posts( array( 'post_type' => $topics_type, 'post_status' => 'publish', 'posts_per_page' => 40, 'orderby' => 'date', 'order' => 'DESC', 'no_found_rows' => true ) );
$forums = get_posts( array( 'post_type' => $forums_type, 'post_status' => 'publish', 'posts_per_page' => 40, 'orderby' => 'menu_order title', 'order' => 'ASC', 'no_found_rows' => true ) );
?>
<main id="main-content" class="atelier-page atelier-page--<?php echo esc_attr( $page_slug ); ?>">
<?php if ( 'discussions' === $page_slug ) : ?>
	<header class="atelier-page__hero"><p class="atelier-kicker">Archives publiques</p><h1>Discussions</h1><p>Chaque sujet est une source consultable : un titre précis, un contexte, des réponses et un espace clairement identifié.</p></header>
	<section class="atelier-page__section" aria-labelledby="atelier-discussions-title"><header class="atelier-section-heading"><p>Index chronologique</p><h2 id="atelier-discussions-title">Toutes les discussions</h2></header><div class="atelier-topic-index">
	<?php if ( $topics ) : foreach ( $topics as $topic ) : $forum_id = function_exists( 'bbp_get_topic_forum_id' ) ? (int) bbp_get_topic_forum_id( $topic->ID ) : 0; ?>
		<article class="atelier-topic-index__item" data-content-kind="forum-topic"><p class="atelier-topic-index__number">SOURCE <?php echo esc_html( str_pad( (string) $topic->ID, 3, '0', STR_PAD_LEFT ) ); ?></p><h3><a href="<?php echo esc_url( get_permalink( $topic ) ); ?>"><?php echo esc_html( get_the_title( $topic ) ); ?></a></h3><p class="atelier-topic-index__summary"><?php echo esc_html( wp_trim_words( wp_strip_all_tags( $topic->post_content ), 30 ) ); ?></p><footer><span><?php echo esc_html( get_the_author_meta( 'display_name', (int) $topic->post_author ) ?: 'Membre' ); ?></span><time datetime="<?php echo esc_attr( get_post_time( DATE_W3C, true, $topic ) ); ?>"><?php echo esc_html( get_the_date( 'd.m.Y', $topic ) ); ?></time><?php if ( $forum_id && function_exists( 'bbp_get_forum_permalink' ) ) : ?><a href="<?php echo esc_url( bbp_get_forum_permalink( $forum_id ) ); ?>"><?php echo esc_html( bbp_get_forum_title( $forum_id ) ); ?></a><?php endif; ?><span><?php echo esc_html( function_exists( 'bbp_get_topic_reply_count' ) ? (int) bbp_get_topic_reply_count( $topic->ID ) : 0 ); ?> réponses</span><span><?php echo esc_html( atelier_total_upvotes( $topic->ID ) ); ?> votes</span></footer></article>
	<?php endforeach; else : ?><p class="atelier-empty">Aucune discussion publique n’est encore archivée.</p><?php endif; ?>
	</div></section>
	<section id="new-post" class="atelier-page__composer" aria-labelledby="atelier-page-composer-title"><header class="atelier-section-heading"><p>Nouvelle source</p><h2 id="atelier-page-composer-title">Ouvrir une discussion</h2></header><?php if ( is_user_logged_in() && function_exists( 'bbp_get_template_part' ) ) : bbp_get_template_part( 'form', 'topic' ); else : ?><p>Connectez-vous pour choisir un espace et publier une nouvelle discussion.</p><a class="atelier-button atelier-button--primary" href="<?php echo esc_url( wp_login_url( get_permalink() . '#new-post' ) ); ?>">Se connecter</a><?php endif; ?></section>
<?php elseif ( 'espaces' === $page_slug ) : ?>
	<header class="atelier-page__hero"><p class="atelier-kicker">Index des espaces</p><h1>Espaces</h1><p>Choisissez le contexte qui donnera à votre discussion la meilleure chance d’être retrouvée et prolongée.</p></header>
	<section class="atelier-page__section" aria-labelledby="atelier-spaces-title"><header class="atelier-section-heading"><p>Communauté structurée</p><h2 id="atelier-spaces-title">Forums disponibles</h2></header><div class="atelier-space-grid"><?php if ( $forums ) : foreach ( $forums as $forum ) : ?><article class="atelier-space-card"><p>ESPACE <?php echo esc_html( str_pad( (string) $forum->ID, 3, '0', STR_PAD_LEFT ) ); ?></p><h2><a href="<?php echo esc_url( get_permalink( $forum ) ); ?>"><?php echo esc_html( get_the_title( $forum ) ); ?></a></h2><p><?php echo esc_html( wp_trim_words( wp_strip_all_tags( $forum->post_content ), 22 ) ); ?></p><footer><span><?php echo esc_html( function_exists( 'bbp_get_forum_topic_count' ) ? (int) bbp_get_forum_topic_count( $forum->ID ) : 0 ); ?> sujets</span><span><?php echo esc_html( atelier_forum_reply_total( $forum->ID ) ); ?> réponses</span><a href="<?php echo esc_url( get_permalink( $forum ) ); ?>">Lire l’espace <span aria-hidden="true">→</span></a></footer></article><?php endforeach; else : ?><p class="atelier-empty">Les espaces de discussion seront bientôt publiés.</p><?php endif; ?></div></section>
<?php elseif ( 'methodes' === $page_slug ) : ?>
	<header class="atelier-page__hero atelier-page__hero--ink"><p class="atelier-kicker">Méthodes de contribution</p><h1>Faire d’une conversation une ressource durable.</h1><p>Un bon sujet donne assez de contexte pour être relu, cité et prolongé. Les réponses restent attachées à la source, avec leur auteur, leur date et leur rang.</p><a class="atelier-button atelier-button--light" href="<?php echo esc_url( atelier_discussions_url() ); ?>#new-post">Ouvrir une discussion <span aria-hidden="true">→</span></a></header>
	<section class="atelier-page__method-grid" aria-label="Méthode Atelier"><article><span>01</span><h2>Nommer le problème</h2><p>Formulez la question, le fait ou la décision dans un titre précis et durable.</p></article><article><span>02</span><h2>Donner le contexte</h2><p>Ajoutez les hypothèses, contraintes et sources nécessaires à une lecture honnête.</p></article><article><span>03</span><h2>Choisir le bon espace</h2><p>Classez la discussion dans le forum qui aide les prochains lecteurs à la retrouver.</p></article></section>
<?php elseif ( 'mon-espace' === $page_slug ) : ?>
	<?php if ( ! is_user_logged_in() ) : ?><header class="atelier-page__hero"><p class="atelier-kicker">Espace membre</p><h1>Retrouver vos contributions.</h1><p>Connectez-vous pour consulter vos discussions, vos réponses et vos informations de membre.</p></header><section class="atelier-member-login" aria-labelledby="atelier-login-title"><h2 id="atelier-login-title">Se connecter</h2><?php wp_login_form( array( 'echo' => true, 'redirect' => get_permalink(), 'label_username' => 'Identifiant ou adresse e-mail', 'label_password' => 'Mot de passe', 'label_log_in' => 'Entrer dans mon espace', 'remember' => true ) ); ?><p><a href="<?php echo esc_url( wp_lostpassword_url( get_permalink() ) ); ?>">Mot de passe oublié ?</a></p></section>
	<?php else : $user_id = get_current_user_id(); $user = wp_get_current_user(); $member_posts = get_posts( array( 'post_type' => array( $topics_type, function_exists( 'bbp_get_reply_post_type' ) ? bbp_get_reply_post_type() : 'reply' ), 'post_status' => 'publish', 'author' => $user_id, 'posts_per_page' => 30, 'orderby' => 'date', 'order' => 'DESC', 'no_found_rows' => true ) ); $community_ready = class_exists( 'PFC_Community' ); $member_notifications = $community_ready ? PFC_Community::notifications( $user_id, 10 ) : array(); $member_unread = $community_ready ? PFC_Community::unread_count( $user_id ) : 0; $member_votes = $community_ready ? PFC_Community::received_upvotes( $user_id ) : 0; $member_is_svip = in_array( 'atelier_svip', (array) $user->roles, true ); ?>
		<header class="atelier-page__hero"><p class="atelier-kicker">Espace membre · @<?php echo esc_html( $user->user_nicename ); ?></p><h1><?php echo esc_html( $user->display_name ); ?></h1><p>Votre archive publique rassemble les discussions et réponses que vous avez choisies de laisser dans l’atelier.</p></header><section class="atelier-profile__layout"><section class="atelier-profile__stream" aria-labelledby="atelier-member-contributions"><header class="atelier-section-heading"><p>Votre trace publique</p><h2 id="atelier-member-contributions">Contributions documentées</h2></header><?php if ( $member_posts ) : foreach ( $member_posts as $member_post ) : $is_reply = function_exists( 'bbp_get_reply_post_type' ) && $member_post->post_type === bbp_get_reply_post_type(); $member_url = $is_reply && function_exists( 'bbp_get_reply_url' ) ? bbp_get_reply_url( $member_post->ID ) : get_permalink( $member_post ); ?><article class="atelier-contribution"><p class="atelier-contribution__kind"><?php echo esc_html( $is_reply ? 'Réponse' : 'Discussion' ); ?> · <time datetime="<?php echo esc_attr( get_post_time( DATE_W3C, true, $member_post ) ); ?>"><?php echo esc_html( get_the_date( 'd.m.Y', $member_post ) ); ?></time></p><h2><a href="<?php echo esc_url( $member_url ); ?>"><?php echo esc_html( get_the_title( $member_post ) ?: 'Réponse archivée' ); ?></a></h2><p><?php echo esc_html( wp_trim_words( wp_strip_all_tags( $member_post->post_content ), 32 ) ); ?></p></article><?php endforeach; else : ?><p class="atelier-empty">Aucune contribution publique n’est encore archivée pour ce membre.</p><?php endif; ?></section><aside class="atelier-profile__aside"><p class="atelier-kicker">Compte actif</p><p>Vous pouvez publier une discussion, choisir son espace et suivre les réponses.</p><dl class="atelier-member-stats"><div><dt>Votes reçus</dt><dd><?php echo esc_html( number_format_i18n( $member_votes ) ); ?></dd></div><div><dt>Notifications</dt><dd><?php echo esc_html( number_format_i18n( $member_unread ) ); ?></dd></div></dl><?php if ( $member_is_svip ) : ?><p class="atelier-member-badge">Membre SVIP</p><?php endif; ?><a class="atelier-button atelier-button--primary" href="<?php echo esc_url( atelier_discussions_url() ); ?>#new-post">Créer une discussion</a><?php if ( $community_ready ) : ?><section class="atelier-notifications" aria-labelledby="atelier-notifications-title"><header><p class="atelier-kicker">Suivi</p><h2 id="atelier-notifications-title">Notifications<?php if ( $member_unread ) : ?> <span class="atelier-notifications__count"><?php echo esc_html( $member_unread ); ?></span><?php endif; ?></h2></header><?php if ( $member_notifications ) : ?><ol><?php foreach ( $member_notifications as $notification ) : ?><li class="<?php echo empty( $notification->is_read ) ? 'is-unread' : ''; ?>"><a href="<?php echo esc_url( $notification->url ); ?>"><?php echo esc_html( $notification->message ); ?><time datetime="<?php echo esc_attr( gmdate( DATE_W3C, strtotime( $notification->created_at ) ) ); ?>"><?php echo esc_html( wp_date( 'd.m.Y H:i', strtotime( $notification->created_at ) ) ); ?></time></a></li><?php endforeach; ?></ol><?php if ( $member_unread ) : ?><button type="button" class="atelier-text-button" data-pfc-mark-read>Marquer comme lues</button><?php endif; else : ?><p class="atelier-empty">Aucune notification pour le moment. Suivez une discussion pour être averti d’une nouvelle réponse.</p><?php endif; ?></section><?php endif; ?><a class="atelier-backlink" href="<?php echo esc_url( wp_logout_url( home_url( '/' ) ) ); ?>">Se déconnecter</a></aside></section>
	<?php endif; ?>
<?php else : ?>
	<header class="atelier-page__hero"><p class="atelier-kicker">Atelier</p><h1><?php the_title(); ?></h1></header><section class="atelier-page__content"><?php the_content(); ?></section>
<?php endif; ?>
</main>
<?php get_footer();
